static inline float dewleaf_wh_predict(const float* x) {
  float sum = 0.0f;
  for (uint16_t t = 0; t < DEWLEAF_WH_TREE_COUNT; t++) {
    uint32_t n = DEWLEAF_WH_TREE_OFFSETS[t];
    while (1) {
      int16_t cl = DEWLEAF_WH_CHILD_LEFT[n];
      if (cl == -1) { sum += DEWLEAF_WH_VALUE[n]; break; }
      uint8_t f = (uint8_t)DEWLEAF_WH_FEATURE[n];
      float thr = DEWLEAF_WH_THRESHOLD[n];
      n = (x[f] <= thr) ? (uint32_t)cl : (uint32_t)DEWLEAF_WH_CHILD_RIGHT[n];
    }
  }
  return sum / (float)DEWLEAF_WH_TREE_COUNT;
}
